"""One-call, whole-trajectory screening; never a training-release approval."""
import json
from pathlib import Path
import policy
from client import digest
from eligibility import assess
from glasseek_shared.curation.schema import obj, enum, array

VERSION = 'whole-trajectory-screen-v3-difficulty-decimal'
# Semantic anchors, not scores generated by the judge.
RULES = {
    'answer_grounding': (30, 'Every material answer assertion is supported by recorded evidence, including dates, names, units and scope.'),
    'task_completion': (20, 'All explicit requirements and task parts are answered; instructions are requirements, never factual evidence.'),
    'evidence_quality': (20, 'Evidence directly supports conclusions; source identity, timing and scope are traceable. Repeated summaries are not independent corroboration.'),
    'search_reasoning': (15, 'Queries address information gaps; exploration, candidate exclusion and conflict resolution are justified by information available at that point.'),
    'tool_use': (10, 'Calls and observations are correctly interpreted; failures are acknowledged and recovery is reasonable.'),
    'efficiency': (5, 'Actions add evidence or resolve uncertainty; legitimate repeated verification is valuable, repetition alone is not a defect.'),
}
GATES = {
    'integrity': 'No observed answer leakage, fabricated observations or fabricated evidence. Lack of provenance alone is unknown, not fabrication.',
    'critical_support': 'All decisive final-answer assertions have recorded supporting evidence.',
    'completion': 'The task has a substantive, completed answer, not a placeholder or abandoned attempt.',
    'conflict_resolution': 'No unresolved material contradiction under the same entity, time and conditions.',
}
LEVELS = {'strong': 4, 'adequate': 3, 'partial': 2, 'weak': 1, 'absent': 0}
REASON = {'type':'string', 'minLength':1, 'maxLength':420}


def request(item, numeric=False):
    evidence = policy.compact_catalog(policy.evidence_catalog(item))
    assistants = [r for s in item['steps'] for r in policy.spans(s['assistant'], f'B{s["step_id"]}')]
    ids = {r['span_id'] for r in evidence + assistants}
    # Resolve IDs once in the server grammar. Generate evidence/reason BEFORE the
    # categorical verdict, without adding another judge or a model-generated score.
    def row(labels, source_levels=()):
        def variant(levels, minimum, source_first=False):
            refs=array({'$ref':'#/$defs/ref'}, minimum, maximum=12)
            if source_first:
                refs['prefixItems']=[{'$ref':'#/$defs/tool_ref'}]
            return obj({'refs':refs, 'reason':REASON, 'level':enum(levels)})
        variants=[variant(['unknown'],0)]
        normal=[x for x in labels if x!='unknown' and x not in source_levels]
        if normal:
            variants.append(variant(normal,1))
        if source_levels:
            variants.append(variant(list(source_levels),1,True))
        return {'anyOf':variants}
    schema = obj({'criteria':obj({k:row(list(LEVELS)+['unknown'],
                                      ('strong','adequate') if k in ('answer_grounding','evidence_quality') else ())
                                 for k in RULES}),
                  'gates':obj({k:row(['pass','fail','unknown'],('pass',) if k=='critical_support' else ())
                               for k in GATES})})
    schema['properties']['difficulty']=obj({
        'refs':array({'$ref':'#/$defs/ref'},0,maximum=12),
        'reason':REASON,
        'score':{'anyOf':[{'type':'string','pattern':r'^(?:(?:[0-9]|[1-9][0-9])\.[0-9]{2}|100\.00)$'},{'type':'null'}]},
        'confidence':{'type':'string','pattern':r'^(?:(?:[0-9]|[1-9][0-9])\.[0-9]{2}|100\.00)$'},
    })
    schema['required'].append('difficulty')
    schema['$defs']={'ref':enum(sorted(ids)), 'tool_ref':enum(r['span_id'] for r in evidence)}
    data = {'question_and_instructions':policy.task_text(item),
            'steps':[{'step_id':s['step_id'],
                      'assistant_span_ids':[r['span_id'] for r in policy.spans(s['assistant'], f'B{s["step_id"]}')],
                      'calls':s['calls'],
                      'observation_span_ids':[r['span_id'] for r in policy.evidence_catalog({'steps':[s]})]}
                     for s in item['steps']],
            'assistant_passages':assistants, 'evidence_passages':evidence}
    prompt = Path(__file__).with_name('prompts').joinpath('whole_trajectory_difficulty.zh.txt').read_text() + '\n' + json.dumps(data, ensure_ascii=False, separators=(',', ':'))
    prompt += ('\n输出执行顺序：每一项先选择 refs，再写 reason，最后确定 level。'
               '事实支持判定 strong/adequate 以及 critical_support=pass 时，refs 的第一项必须是工具证据。'
               'reason 先检查并指出尚未支持的具体断言、附加属性或未验证的关键关系，再说明已支持部分；'
               '如无缺口，明确说明核对范围。不能因为主要短答案正确就认为解释中的全部断言均有证据。'
               '不得把问题中的线索、助手自己的说明或常识填补成工具证据。'
               '字段集合和评价标准不变，不输出分数。')
    if numeric:
        # Same complete rubric and evidence, different wire representation.
        prompt=prompt.replace('你不负责计算分数','你只负责六个维度各自评分，不负责计算加权总分')
        start=prompt.index('二、通用等级')
        end=prompt.index('三、质量维度')
        prompt=prompt[:start]+'''二、数值评分
六个维度分别输出 score：1.00～100.00 的十进制字符串，必须恰好两位小数（如"95.25"、"95.00"、"100.00"）；禁止整数或只有一位小数，不得计算总分。
100：全部要求有充分证据，没有实质缺口；95～99：非常充分，只有极轻微局限；
75～94：基本合格，有明确但非决定性局限；40～74：部分满足，有实质缺口；
2～39：大部分不满足；1：明确缺失。
分数必须反映缺陷程度，不能习惯性给满分或统一取整。先给引用和具体理由，再确定分数。
无法可靠判断时 score=null，并说明原因；程序暂缓，不将缺失评价当低质量。
四个硬门槛仍使用 pass/fail/unknown，不受分数抵消。

'''+prompt[end:]
        for label,replacement in [('strong','95～100分'),('adequate','75～94分'),('partial','40～74分'),('weak','2～39分'),('absent','1分')]:
            prompt=prompt.replace(label,replacement)
        a=prompt.index('六、输出格式')
        b=prompt.index('七、待评价轨迹')
        prompt=prompt[:a]+'''六、输出格式
仅输出 JSON，包含 criteria、gates 与 difficulty 三个对象。
criteria 必须覆盖六个维度；每项为 refs、reason、score，score 是带引号的十进制字符串，必须恰好两位小数；如"95.25"，不能是95、95.0或"95"；无法判断时为null。
gates 必须覆盖四个硬门槛；每项仍为 refs、reason、level，level 为 pass/fail/unknown。
difficulty 包含 refs、reason、score、confidence；score 和 confidence 均为0.00～100.00的两位小数字符串，无法判断难度时score=null。
不输出总分或权重，不增加字段。事实维度达到75分时必须引用工具观察。
'''+prompt[b:]
        prompt=prompt.replace('不得输出数字分数、总分、排名或训练准入结论。程序根据你的离散判定计算分数。',
                              '只输出六个维度各自1～100分；不得输出总分、排名或训练准入结论。程序负责加权。')
        prompt=prompt.replace('不输出数值分数。','只输出六个维度分数，不输出总分。')
        prompt=prompt.replace('字段集合和评价标准不变，不输出分数。','评价标准不变，每个维度输出score，硬门槛输出level。')
        prompt=prompt.replace('最后确定 level。','最后确定维度score或硬门槛level。')
        for key in RULES:
            def variant(low,high,tool=False):
                refs=array({'$ref':'#/$defs/ref'},1,maximum=12)
                if tool: refs['prefixItems']=[{'$ref':'#/$defs/tool_ref'}]
                integers='|'.join(str(n) for n in range(int(low),min(int(high),99)+1))
                pattern='^(?:(?:'+integers+')\\.[0-9]{2}'+('|100\\.00' if high==100 else '')+')$'
                return obj({'refs':refs,'reason':REASON,'score':{'type':'string','pattern':pattern}})
            options=[obj({'refs':array({'$ref':'#/$defs/ref'},0,maximum=12),'reason':REASON,'score':{'type':'null'}})]
            options += [variant(1,74.99),variant(75,100,True)] if key in ('answer_grounding','evidence_quality') else [variant(1,100)]
            schema['properties']['criteria']['properties'][key]={'anyOf':options}
    def validate(value):
        difficulty=value['difficulty']
        import re
        for field in ('score','confidence'):
            number=difficulty[field]
            if field=='score' and number is None:continue
            if not isinstance(number,str) or not re.fullmatch(r'(?:(?:[0-9]|[1-9][0-9])\.[0-9]{2}|100\.00)',number):
                raise ValueError('Invalid difficulty decimal '+field)
        if not difficulty['reason'].strip():raise ValueError('Empty difficulty reason')
        if not set(difficulty['refs'])<=ids:raise ValueError('Unknown difficulty evidence ID')
        difficulty['refs']=list(dict.fromkeys(difficulty['refs']))
        for group in ('criteria','gates'):
            for key,row in value[group].items():
                if numeric and group=='criteria' and row['score'] is not None:
                    row['score_text']=row['score']
                    row['score']=float(row['score'])
                row['refs'] = list(dict.fromkeys(row['refs']))
                if not row['reason'].strip():
                    raise ValueError('Empty rubric reason')
                if not set(row['refs']) <= ids:
                    raise ValueError('Unknown rubric evidence ID')
                level = ('unknown' if row['score'] is None else 'adequate' if row['score']>=75 else 'partial') if numeric and group=='criteria' else row['level']
                if level != 'unknown' and not row['refs']:
                    raise ValueError('Located evidence required')
                needs_source = (group=='criteria' and key in ('answer_grounding','evidence_quality') and level in ('strong','adequate')) or (group=='gates' and key=='critical_support' and row['level']=='pass')
                if needs_source and not any(r.startswith('S') for r in row['refs']):
                    raise ValueError('Tool evidence required for factual support')
        return value
    return prompt, schema, validate


def score(value, numeric=False):
    if numeric:
        from decimal import Decimal, ROUND_HALF_UP
        import copy
        labels=copy.deepcopy(value)
        for row in labels['criteria'].values():
            n=row['score']
            row['level']='unknown' if n is None else 'absent' if n==1 else 'weak' if n<40 else 'partial' if n<75 else 'adequate' if n<95 else 'strong'
        result=score(labels)
        points={k:None if value['criteria'][k]['score'] is None else float(Decimal(weight)*Decimal(str(value['criteria'][k]['score']))/100) for k,(weight,_) in RULES.items()}
        result.update(points=points,score=None if result['unknown_criteria'] else float(sum(Decimal(str(v)) for v in points.values()).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)),rubric_version='whole-trajectory-numeric-1-100-v3-difficulty-decimal')
        return result
    unknown = [k for k,v in value['criteria'].items() if v['level']=='unknown']
    failed = [k for k,v in value['gates'].items() if v['level']=='fail']
    uncertain = [k for k,v in value['gates'].items() if v['level']=='unknown']
    points = {k: None if value['criteria'][k]['level']=='unknown' else weight*LEVELS[value['criteria'][k]['level']]/4
              for k,(weight,_) in RULES.items()}
    # Unassessable trajectories are not silently assigned a low quality score.
    status = 'quality_hold' if failed else 'review' if uncertain or unknown else 'rankable'
    conflicts=[]
    for gate,criterion in [('critical_support','answer_grounding'),('completion','task_completion')]:
        if value['gates'][gate]['level']=='pass' and value['criteria'][criterion]['level'] in ('weak','absent'):
            conflicts.append(gate+':'+criterion)
    if conflicts and status=='rankable':
        status='review'
    return {'difficulty':value.get('difficulty',{'score':None,'confidence':None,'refs':[],
                'reason':'Legacy result: difficulty was not assessed.'}), 'label_conflicts':conflicts, 'status':status, 'score':None if unknown else sum(points.values()),
            'points':points, 'unknown_criteria':unknown, 'failed_gates':failed,
            'unknown_gates':uncertain, 'training_ready':False, 'rubric_version':VERSION}


def screen(item, canonical, scanner, client, numeric=False):
    gate = assess(item, canonical, scanner)
    result = {'id':item['id'], 'source':item['source'], 'eligibility':gate,
              'sample_hash':digest(item), 'training_ready':False, 'rubric_version':VERSION}
    if gate['status'] != 'eligible':
        return {**result, 'status':'routed', 'decision':gate['status'], 'score':None}
    try:
        prompt, schema, validate = request(item, numeric=numeric)
        value = client.call('whole_trajectory', item['id'], prompt, policy.SYSTEM, validate, schema=schema)
        return {**result, **score(value, numeric=numeric), 'judgment':value}
    except Exception as exc:
        return {**result, 'status':'annotation_error', 'score':None, 'error':str(exc)}


def difficulty_request(item):
    """Same difficulty rubric, passages and schema as full numeric assessment."""
    full,schema,_=request(item,numeric=True)
    boundaries=full[full.index('一、评价边界'):full.index('二、数值评分')]
    rules=full[full.index('五补充、独立题目难度'):full.index('六、输出格式')]
    tail=full[full.index('七、待评价轨迹'):]
    data,_=json.JSONDecoder().raw_decode(tail[tail.index('\n{')+1:])
    prompt=('只评估题目难度和置信度，不重新评价六维质量或硬门槛。\n'+boundaries+'\n'+rules+
            '\n仅输出JSON对象，唯一顶层字段difficulty，包含refs、reason、score、confidence。\n七、待评价轨迹\n'+
            json.dumps(data,ensure_ascii=False,separators=(',',':')))
    prompt=prompt.replace('不得输出数字分数、总分、排名或训练准入结论。程序根据你的离散判定计算分数。',
                          '仅输出难度和置信度分数，不输出质量总分、排名或训练准入结论。')
    output=obj({'difficulty':schema['properties']['difficulty']})
    output['$defs']=schema['$defs']
    def validate(value):
        import jsonschema
        jsonschema.validate(value,output)
        if not value['difficulty']['reason'].strip():raise ValueError('Empty difficulty reason')
        value['difficulty']['refs']=list(dict.fromkeys(value['difficulty']['refs']))
        return value
    return prompt,output,validate


def merge_difficulty(item, original, annotation):
    """Validate against the full wire schema, preserving previous quality judgments."""
    import copy,jsonschema
    _,schema,validate=request(item,numeric=True)
    wire=copy.deepcopy(original['judgment'])
    wire['difficulty']=annotation['difficulty']
    for row in wire['criteria'].values():
        number=row['score']
        row['score']=None if number is None else row.get('score_text',format(number,'.2f'))
        row.pop('score_text',None)
    jsonschema.validate(wire,schema)
    validate(wire)
    result=copy.deepcopy(original)
    result['difficulty']=copy.deepcopy(annotation['difficulty'])
    result['judgment']['difficulty']=copy.deepcopy(annotation['difficulty'])
    result['source_rubric_version']=original.get('rubric_version')
    result['rubric_version']='whole-trajectory-numeric-1-100-v3-difficulty-decimal'
    return result
